// Push handlers for Nothing BOT Curate. Pulled into the app's one service worker (generated by vite-plugin-pwa)
// with Workbox importScripts, so there is a single worker at the root scope.
// The worker sends data-only FCM messages: { kind, title, body, link } (apps/worker/src/notify.ts).

self.addEventListener("push", (event) => {
  let payload = {};
  try {
    payload = event.data ? event.data.json() : {};
  } catch {
    payload = { data: { body: event.data ? event.data.text() : "" } };
  }
  const n = payload.notification || {};
  const d = payload.data || {};
  const title = d.title || n.title || "Nothing BOT Curate";
  const body = d.body || n.body || "";
  const link = d.link || (payload.fcmOptions && payload.fcmOptions.link) || "/settings#whatsapp";

  event.waitUntil(
    (async () => {
      const wins = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      const visible = wins.filter((w) => w.visibilityState === "visible");
      if (visible.length) {
        // The app is on screen: it shows a toast instead of a system notification.
        visible.forEach((w) => w.postMessage({ type: "spot-push", kind: d.kind, title, body, link }));
        return;
      }
      await self.registration.showNotification(title, {
        body,
        icon: "/icons/icon-192.png",
        badge: "/icons/icon-192.png",
        tag: d.kind || "spot",
        data: { link },
      });
    })(),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const raw = (event.notification.data && event.notification.data.link) || "/settings#whatsapp";
  // Always land on this origin (the link in the message is the production URL; dev and previews differ).
  const u = new URL(raw, self.location.origin);
  const target = self.location.origin + u.pathname + u.search + u.hash;
  event.waitUntil(
    (async () => {
      const wins = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      const win = wins[0];
      if (win) {
        try {
          await win.focus();
          await win.navigate(target);
          return;
        } catch {
          /* fall through and open a new window */
        }
      }
      await self.clients.openWindow(target);
    })(),
  );
});
